functions.stepHandDragPhysics:
function stepHandDragPhysics(body,target,dt,reduced=false){
  dt=Math.min(.034,Math.max(.001,dt));
  if(reduced){body.x=target.x;body.y=target.y;body.vx=body.vy=body.angle=body.tilt=0;body.scale=1;return body;}
  const stiffness=190,damping=23;
  body.vx+=(stiffness*(target.x-body.x)-damping*body.vx)*dt;
  body.vy+=(stiffness*(target.y-body.y)-damping*body.vy)*dt;
  body.x+=body.vx*dt;body.y+=body.vy*dt;
  // Keep rapid cross-screen gestures close enough to the hand to feel connected.
  const dx=target.x-body.x,dy=target.y-body.y,distance=Math.hypot(dx,dy);
  if(distance>65){body.x=target.x-dx/distance*65;body.y=target.y-dy/distance*65;}
  const ease=1-Math.exp(-14*dt);
  body.angle+=(Math.max(-12,Math.min(12,body.vx*.012))-body.angle)*ease;
  body.tilt+=(Math.max(-7,Math.min(7,-body.vy*.008))-body.tilt)*ease;
  body.scale+=(1.055+Math.min(.02,Math.hypot(body.vx,body.vy)/40000)-body.scale)*ease;
  return body;
}

functions.stepTableCardSlide:
function stepTableCardSlide(body,dt,bounds){
  const speed=Math.hypot(body.vx,body.vy),friction=2400;
  if(speed>0){
    const elapsed=Math.min(Math.max(0,dt),speed/friction),distance=speed*elapsed-friction*elapsed*elapsed/2;
    body.x+=body.vx/speed*distance;body.y+=body.vy/speed*distance;
    const remaining=Math.max(0,speed-friction*elapsed)/speed;body.vx*=remaining;body.vy*=remaining;
  }
  const spinDecay=Math.exp(-9*Math.max(0,dt));body.angle+=body.spin*(1-spinDecay)/9;body.spin*=spinDecay;
  const x=Math.max(bounds.left,Math.min(bounds.right,body.x)),y=Math.max(bounds.top,Math.min(bounds.bottom,body.y));
  if(x!==body.x)body.vx=0;if(y!==body.y)body.vy=0;body.x=x;body.y=y;
  return body;
}

functions.startTableCardSlide:
function startTableCardSlide(drag,releasedAt){
  if(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches || drag.node.classList.contains('peek-taken'))return;
  const age=Math.max(0,releasedAt-drag.lastMotionAt),decay=Math.exp(-age/65),speed=Math.hypot(drag.vx,drag.vy)*decay;
  if(age>100 || speed<45)return;
  const node=drag.node,rect=node.getBoundingClientRect(),maxTravel=Math.max(32,Math.min(140,rect.width*.9));
  const limited=Math.min(speed,Math.sqrt(2*2400*maxTravel)),ratio=limited/Math.hypot(drag.vx,drag.vy);
  const body={x:rect.left+rect.width/2,y:rect.top+rect.height/2,vx:drag.vx*ratio,vy:drag.vy*ratio,
    angle:drag.rotation,spin:Math.max(-28,Math.min(28,(drag.vx*drag.offsetY-drag.vy*drag.offsetX)*.0007))};
  const slide={body,frame:null,previous:performance.now()};tableCardSlides.set(node,slide);node.classList.add('table-card-sliding');
  node.style.setProperty('--table-angle',`${body.angle}deg`);
  const tick=now=>{
    if(tableCardSlides.get(node)!==slide)return;
    if(node.isConnected===false || !movableTableCardEnabled(node)){stopTableCardSlide(node,false);return;}
    const dt=(now-slide.previous)/1000;slide.previous=now;
    // A backgrounded tab must not resume an old throw when it becomes visible again.
    if(dt>.12){stopTableCardSlide(node);return;}
    stepTableCardSlide(body,dt,{left:24,top:24,right:window.innerWidth-24,bottom:window.innerHeight-24});
    moveTitleCard(node,body.x,body.y);node.style.setProperty('--table-angle',`${body.angle}deg`);
    node.dataset.ignoreClickUntil=String(Date.now()+100);
    if(Math.hypot(body.vx,body.vy)<8 && Math.abs(body.spin)<1){stopTableCardSlide(node);return;}
    slide.frame=requestAnimationFrame(tick);
  };
  slide.frame=requestAnimationFrame(tick);
}

functions.onTitleCardPointerMove:
function onTitleCardPointerMove(event){
  const drag=titleCardDrag;if(!drag || drag.pointerId!==event.pointerId)return;
  if(!drag.moved && Math.hypot(event.clientX-drag.startX,event.clientY-drag.startY)>5){
    drag.moved=true;liftTitleCard(drag.node);
    try{drag.node.setPointerCapture(drag.pointerId);}catch(_error){}
  }
  if(!drag.moved)return;
  drag.node.classList.add('table-card-dragging');
  const point=moveTitleCard(drag.node,event.clientX-drag.offsetX,event.clientY-drag.offsetY),time=tableCardEventTime(event),dt=(time-drag.sampleTime)/1000;
  if(dt>0){
    const dx=point.x-drag.samplePoint.x,dy=point.y-drag.samplePoint.y,blend=1-Math.exp(-dt/.035);
    drag.vx+=(dx/dt-drag.vx)*blend;drag.vy+=(dy/dt-drag.vy)*blend;
    if(Math.hypot(dx,dy)>.2)drag.lastMotionAt=time;
    drag.samplePoint=point;drag.sampleTime=time;
  }
  const twist=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ? 0 : Math.max(-7,Math.min(7,(drag.vx*drag.offsetY-drag.vy*drag.offsetX)*.0005));
  drag.rotation=drag.angle+twist;drag.node.style.setProperty('--table-angle',`${drag.rotation}deg`);
}
